fn check(ok:bool){if !ok{let _=fail(0);}}fn fail(x:u8)->u8{1/x}struct Tail<T:?Sized>{v:T}struct Outer<T:?Sized>{head:u32,inner:Tail<T>}const R:&Outer<[u8]>=&Outer{head:37,inner:Tail{v:[1u8,2]}};const I:&Tail<[u8]>=&R.inner;const V:&[u8]=&I.v;const fn take(r:&Tail<[u8]>)->u8{match &r.v{[a,b]=>*a+*b,_=>0}}fn main(){check(R.head==37);check(take(I)==3);check(match V{[a,b]=>*a+*b==3,_=>false});}
